// Source of truth: src/content/patents.json (transcribed from VP_Annexure.pdf, pp. 9–23)
import raw from "../content/patents.json";

const STATUS = {
  "Granted section": "Granted",
  "PCT / US applications": "PCT/US",
  "Indian applications": "Indian",
};

const googlePatentsUrl = (identifier) => {
  const s = identifier.replace(/\s+/g, "");
  const us = s.match(/US(\d{1,2},?\d{3},?\d{3})B2/);
  if (us) return `https://patents.google.com/patent/US${us[1].replace(/,/g, "")}B2/en`;
  const usApp = s.match(/US(\d{4})\/(\d{7})A1/);
  if (usApp) return `https://patents.google.com/patent/US${usApp[1]}${usApp[2]}A1/en`;
  const wo = s.match(/WO(\d{4})\/(\d{6})(A\d)?/);
  if (wo) return `https://patents.google.com/patent/WO${wo[1]}${wo[2]}${wo[3] || ""}/en`;
  return null;
};

export const PATENTS = raw.map((p) => ({
  id: p.id,
  number: p.number,
  title: p.title,
  inventors: p.inventors,
  identifier: p.identifier,
  documents: p.documents.slice(1),
  year: p.year,
  status: STATUS[p.type],
  jurisdiction: p.jurisdiction,
  url: googlePatentsUrl(p.identifier),
  sourcePages: p.source.pages,
}));

export const PAT_STATUSES = ["Granted", "PCT/US", "Indian"];
export const PAT_YEARS = [...new Set(PATENTS.map((p) => p.year).filter(Boolean))].sort((a, b) => b - a);

